fn is_letter(c: Str) -> Bool {
  return c.len() == 1 and "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".contains(c)
}

fn is_digit(c: Str) -> Bool {
  return c.len() == 1 and "0123456789".contains(c)
}

fn is_ident_start(c: Str) -> Bool {
  return is_letter(c) or c == "_"
}

fn is_ident_char(c: Str) -> Bool {
  return is_letter(c) or is_digit(c) or c == "_"
}

fn is_two_op(t: Str) -> Bool {
  return t == "==" or t == "!=" or t == "<=" or t == ">=" or t == "->"
}

fn is_single(c: Str) -> Bool {
  return ["+", "-", "*", "/", "<", ">", "=", "(", ")", "{", "}", ",", ";"].contains(c)
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
  let cs = src.chars()
  let n = cs.len()
  var out: List[Str] = []
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    if c == " " or c == "\t" or c == "\n" or c == "\r" {
      i = i + 1
    } else if c == "\"" {
      var j = i + 1
      var closed = false
      while j < n and (not closed) {
        let d = cs.get_or(j, "")
        if d == "\\" {
          j = j + 2
        } else if d == "\"" {
          closed = true
        } else {
          j = j + 1
        }
      }
      if not closed {
        return Err("unterminated string")
      }
      out = out.push(cs.slice(i, j + 1).join(""))
      i = j + 1
    } else if is_ident_start(c) {
      var j = i + 1
      while j < n and is_ident_char(cs.get_or(j, "")) {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if is_digit(c) {
      var j = i + 1
      while j < n and is_digit(cs.get_or(j, "")) {
        j = j + 1
      }
      out = out.push(cs.slice(i, j).join(""))
      i = j
    } else if i + 1 < n and is_two_op(c + cs.get_or(i + 1, "")) {
      out = out.push(c + cs.get_or(i + 1, ""))
      i = i + 2
    } else if is_single(c) {
      out = out.push(c)
      i = i + 1
    } else {
      return Err("unexpected " + c)
    }
  }
  return Ok(out)
}
